  if(validSave(copy)){try{if(raw&&!localStorage.getItem(STORE+'_damaged'))localStorage.setItem(STORE+'_damaged',raw)}catch(e){}saveWarning='主存档异常，已使用备用存档恢复。';return {...starter(),...copy};}
