function summon(n){
 ensurePoolState();const b=banner();const p=bannerPity();
 const isBeast=b.type==='beast';
 const useT=isBeast?0:Math.min(n,S.tickets);
 const cost=isBeast?0:(n===10?Math.ceil(1440*(n-useT)/10):useT?0:160);
 const essenceCost=isBeast?(n===10?900:100):0;
 if(S.jade<cost){msg('仙玉不足，请领取试炼补给');return}
 if(S.essence<essenceCost){msg('异兽精魄不足，请领取试炼补给');return}
 if(isBeast)S.essence-=essenceCost;else{S.jade-=cost;S.tickets-=useT;}
 drawResults=[];
 for(let i=0;i<n;i++){
  p.rare++;p.myth++;S.draws++;
  const z=Math.random(); let tier=z<.01?'神话':z<.06?'传说':z<.30?'史诗':'灵品';
  if(p.myth>=80)tier='神话';else if(p.rare>=30&&['史诗','灵品'].includes(tier))tier='传说';
  // A ten-draw contains at least one rare or higher result.
  if(n===10&&i===9&&!drawResults.some(x=>['神话','传说','史诗'].includes(x.tier))&&tier==='灵品')tier='史诗';
  if(tier==='神话'){p.myth=0;p.rare=0}else if(tier==='传说')p.rare=0;
  if(b.type==='hero'){
   let candidates=HEROS.filter(h=>h.tier===tier);
   if(b.id==='faction'){
    const allowed=FACTION_OPTIONS.find(x=>x.id===currentSummonFaction)?.camps||['天庭','道门'];
    const scoped=candidates.filter(h=>allowed.includes(h.camp));
    if(scoped.length)candidates=scoped;
   }
   if(b.id==='limited'&&tier==='神话'&&Math.random()<.5){const h=candidates.find(x=>x.name==='女娲');if(h)candidates=[h]}
   const hero=pick(candidates);if(!hero){throw Error('召唤池未找到候选角色 '+tier)}
   const dup=!!S.units[hero.id];if(dup){S.units[hero.id].shards+=30;S.echoes+=({灵品:5,史诗:8,传说:16,神话:30})[tier];}else S.units[hero.id]={star:1,level:1,shards:0,artifact:0,gear:[null,null,null,null]};
   drawResults.push({type:'hero',id:hero.id,name:hero.name,tier,dup});
  }else if(b.type==='relic'){
   const id=rnd(HEROS.length),hero=HEROS[id];
   const amount=({灵品:2,史诗:5,传说:12,神话:30})[tier];
   S.relicFragments[id]=(S.relicFragments[id]||0)+amount;
   drawResults.push({type:'relic',id,name:hero.artifact,tier,amount,dup:false});
  }else{
   const id=rnd(BEASTS.length),beast=BEASTS[id],amount=({灵品:8,史诗:15,传说:30,神话:60})[tier];
   const dup=!!S.beasts[id];
   if(dup)S.beasts[id].shards+=amount;else S.beasts[id]={level:1,shards:amount};
   drawResults.push({type:'beast',id,name:beast.name,tier,dup,amount});
  }
 }
 if(b.id==='standard'){S.pity=p.rare;S.mythPity=p.myth;}
 if(n===10)S.first=false;
 S.summonHistory=[{pool:b.id,created:Date.now(),results:drawResults.map(x=>({...x}))},...S.summonHistory].slice(0,30);
 modal='summonIntro';render();
 if(revealTimer!==null)clearTimeout(revealTimer);
 revealTimer=setTimeout(()=>{if(modal==='summonIntro'){modal='draw';render()}revealTimer=null},850);
}
function summonResultArt(item){
 if(item.type==='hero')return portrait(HEROS[item.id]);
 if(item.type==='relic')return relicArt(item.id,'result-object');
 return beastArt(item.id,'result-object');
}
function summonResultCard(item,i){
 const subtitle=item.type==='hero'?(item.dup?'神魂 +30':'新结缘'):item.type==='relic'?'残卷 +'+item.amount:(item.dup?'兽魂 +'+item.amount:'新契约');
 return `<div class="drawcard ${rarity(item.tier)}" data-result-id="${item.type}-${item.id}" style="animation-delay:${i*.055}s"><div class="rarity">${item.tier}</div>${summonResultArt(item)}<div class="name">${item.name}</div><div class="tiny">${subtitle}</div></div>`;
}

function ascend(){let u=S.units[selected];if(!u)return;if(u.star>=30){msg('已达到30星最高境界');return}let cost=price(selected);if(u.shards+S.spirit<cost){msg(`神魂不足：还缺 ${cost-u.shards-S.spirit} 枚`);return}let self=Math.min(cost,u.shards);u.shards-=self;S.spirit-=cost-self;u.star++;const realm=STAR_REALMS[starRealm(u.star).stage];if(starRealm(u.star).filled===1&&u.star>1)S.breakthroughNotice={id:selected,star:u.star,at:Date.now()};msg(`${HEROS[selected].name} · ${realm.name}境 第${starRealm(u.star).filled}星 ${starRealm(u.star).filled===1?'突破新境！':'提升成功'}`);render()}
function level(){let u=S.units[selected],cost=1300+u.level*110;if(u.level>=20+u.star*5){msg('已达等级上限，先升星');return}if(S.gold<cost){msg('铜钱不足，去征战获取');return}S.gold-=cost;u.level++;render()}
function toggleTeam(){if(!S.units[selected])return;let index=S.lineup.indexOf(selected);if(index>=0){if(S.lineup.length<=1){msg('至少保留一名神将');return}S.lineup.splice(index,1)}else if(S.lineup.length>=5){msg('最多上阵五位，请先撤下一位');return}else S.lineup.push(selected);msg('神阵已调整');render()}
function bestFrontlineOrder(ids){return [...ids].sort((a,b)=>{
 const priority=id=>{const h=HEROS[id],u=S.units[id],role=h?.role;
  return (role==='护法'?100:role==='破军'?55:role==='灵武'?38:role==='灵医'?-50:0)+hpMax(h,u)/180;};
 return priority(b)-priority(a);});}
function optimizeLineup(){const owned=Object.keys(S.units).map(Number).filter(id=>S.units[id]).sort((a,b)=>power(b)-power(a));
 if(owned.length<=5)return bestFrontlineOrder(owned);
 const candidates=owned.slice(0,28),seeds=[owned.slice(0,5)];
 const eligibleBonds=BOND_RULES.map(b=>({bond:b,ids:b.members.map(n=>HEROS.find(h=>h.name===n)?.id)}))
 .filter(x=>x.ids.every(id=>Number.isInteger(id)&&S.units[id]))
 .sort((a,b)=>b.ids.reduce((v,id)=>v+power(id),0)-a.ids.reduce((v,id)=>v+power(id),0));
 for(const {ids} of eligibleBonds.slice(0,15)){
  ids.forEach(id=>{if(!candidates.includes(id))candidates.push(id)});
  seeds.push([...new Set([...ids,...owned])].slice(0,5));
 }
 let best=seeds[0],bestScore=-Infinity;
 const evaluate=ids=>{
  const ordered=bestFrontlineOrder(ids),score=teamCombatPower(ordered);
  // Attacks and healing still value a robust front line. Avoid all fragile casters.
  const front=ordered.slice(0,2).filter(id=>['护法','破军','灵武'].includes(HEROS[id].role)).length;
  return score+(front?score*.012*front:0);
 };
 for(const seed of seeds){let current=bestFrontlineOrder(seed),score=evaluate(current);
  for(let round=0;round<2;round++){
   let winning=current,winningScore=score;
   for(let slot=0;slot<current.length;slot++)for(const id of candidates){
    if(current.includes(id))continue;
    const variant=[...current];variant[slot]=id;
    const val=evaluate(variant);if(val>winningScore+.01){winning=variant;winningScore=val}
   }
   if(winning===current)break;current=bestFrontlineOrder(winning);score=winningScore;
  }
  if(score>bestScore){best=current;bestScore=score}
 }
 return bestFrontlineOrder(best);
}
function autoTeam(){const before=activeBonds(S.lineup).length;
 S.lineup=optimizeLineup();const after=activeBonds(S.lineup).length;
 msg(`神阵智能编成 · ${after}组羁绊激活（原${before}组）`);render();}
function upArtifact(){let u=S.units[selected],cost=16+u.artifact*10;if(u.artifact>=30){msg('法宝已圆满');return}ensurePoolState();let fragments=S.relicFragments[selected]||0;
 if(fragments>=5){S.relicFragments[selected]-=5;u.artifact++;msg(`${HEROS[selected].artifact} 消耗5张本命残卷，升至${u.artifact}阶`);render();return;}
 if(S.dust<cost){msg('灵材不足，请领取试炼补给');return}S.dust-=cost;u.artifact++;msg(`${HEROS[selected].artifact} 升至${u.artifact}阶`);render()}
function forge(){if(S.gold<6000){msg('铜钱不足');return}S.gold-=6000;let z=Math.random(),rarity=z<.025?4:z<.15?3:z<.52?2:1,g={id:S.uid++,slot:rnd(4),rarity,level:1,seed:rnd(100)};S.gear.push(g);msg(`锻造出 ${gearName(g)}`);render()}
function gearHolder(id){for(let k in S.units){if(S.units[k].gear.includes(id))return '· '+HEROS[k].name+'穿戴中'}return '· 未穿戴'}
function equip(id){let g=S.gear.find(g=>g.id===id);if(!g)return;for(let key in S.units)S.units[key].gear=S.units[key].gear.map(slot=>slot===id?null:slot);S.units[selected].gear[g.slot]=id;modal='';msg('已穿戴 '+gearName(g));render()}
function upGear(slot){let u=S.units[selected],g=S.gear.find(g=>g.id===u.gear[slot]);if(!g)return;let cost=1800+(g.level*700);if(g.level>=20){msg('该装备已强化至20级');return}if(S.gold<cost){msg('铜钱不足');return}S.gold-=cost;g.level++;msg(`${TYPES[slot]} 强化至 +${g.level}`);render()}
function beastDesc(k){return ({ward:'护盾守护',strike:'暴击突袭',weaken:'削弱敌军',heal:'治疗回血',burn:'炎火灼烧',shield:'群体护盾',drain:'伤害吸血',energy:'补充全队灵力',haste:'增加攻击',poison:'群体毒伤'})[k]||'灵能加持'}
function beastDraw(){if(S.essence<100){msg('异兽精魄不足，征战获取');return}S.essence-=100;beastIndex=rnd(BEASTS.length);beastResult=S.beasts[beastIndex]?'dup':'new';if(beastResult==='dup')S.beasts[beastIndex].shards+=20;else S.beasts[beastIndex]={level:1,shards:10};modal='beastDraw';render()}
function beastUp(){let u=S.beasts[beastIndex];if(!u||u.level>=30){msg('异兽已达到30阶');return}let cost=18+u.level*6;if(S.essence<cost){msg('精魄不足');return}S.essence-=cost;u.level++;msg(`${BEASTS[beastIndex].name} 升至 ${u.level} 阶`);render()}
function beastToggle(){let index=S.beastLine.indexOf(beastIndex);if(index>=0)S.beastLine[index]=null;else{let free=S.beastLine.indexOf(null);if(free===-1){msg('双异兽位已满，先撤下一只');return}S.beastLine[free]=beastIndex}render()}
function autoBeast(){S.beastLine=Object.keys(S.beasts).map(Number).sort((a,b)=>S.beasts[b].level-S.beasts[a].level).slice(0,2);while(S.beastLine.length<2)S.beastLine.push(null);render()}
function addStatus(t,kind,n=2){t.status[kind]=Math.max(t.status[kind]||0,n)}function alive(list){return list.filter(x=>x.hp>0)}function lowest(list){return [...alive(list)].sort((a,b)=>a.hp/a.max-b.hp/b.max)[0]}function damage(t,amount,log,source,ignore=false,attacker=null){if(!t||t.hp<=0)return 0;let shield=t.status['护盾值']||0,hit=Math.max(1,Math.floor(amount));if(shield&&!ignore){let absorbed=Math.min(shield,hit);t.status['护盾值']-=absorbed;hit-=absorbed;
 if(attacker&&attacker.hp>0&&t.status['反震']&&absorbed>0){let r=Math.max(1,Math.floor(absorbed*.33));attacker.hp=Math.max(0,attacker.hp-r);log.push(`🛡️ 玄武反震：${attacker.name}受到 ${nfmt(r)} 反伤`)}}
if(!ignore&&t.status['防护'])hit=Math.floor(hit*.76);if(!ignore&&t.status['易伤'])hit=Math.floor(hit*1.25);if(!ignore&&(t.passive==='金身'||t.passive==='山岳'||t.passive==='道心'))hit=Math.floor(hit*.91);if(!ignore&&t.passive==='风行'&&Math.random()<.12){log.push(`${t.name} 闪避了攻击`);return 0}t.hp=Math.max(0,t.hp-hit);if(hit>0)log.push(`${source} → ${t.name} 受到 ${nfmt(hit)} 伤害`);if(!t.enemy&&t.hp<=0&&t.passive==='不屈'&&!t.revived){t.hp=1;t.revived=true;log.push(`${t.name} 触发「不屈」保住最后一点生命！`)}return hit}function heal(t,v,log,source){if(!t)return;let add=Math.min(t.max-t.hp,Math.floor(v));t.hp+=add;if(add>0)log.push(`${source} → ${t.name} 回复 ${nfmt(add)} 生命`)}
let autoBattleTimer=null;
let autoBattleSpeed=1;
function stopAutoBattle(){if(autoBattleTimer!==null){clearTimeout(autoBattleTimer);autoBattleTimer=null}}
function scheduleAutoBattle(){stopAutoBattle();if(page!=='battle'||!battle||battle.over)return;const current=battle;
 autoBattleTimer=setTimeout(()=>{autoBattleTimer=null;if(battle!==current||page!=='battle'||current.over)return;
 try{doTurn(current);render()}catch(e){console.error('Battle failure',e);current.over=true;current.log.push('战斗发生异常，请返回并重试');render()}
 },autoBattleSpeed===2?175:530);
}
function autoBattleMiracle(b,log){if(b.round%3!==0||!alive(b.good).length||!alive(b.enemy).length)return;
 const team=alive(b.good),foes=alive(b.enemy),weak=lowest(team);
 if(team.some(x=>x.kind==='heal'||x.role==='灵医')&&weak&&weak.hp<weak.max*.75){team.forEach(x=>{heal(x,x.max*.12,log,'✿ 五神联动·青莲甘露');delete x.status['灼烧']});log.push('✿ 神阵连携：治疗驱散火种')}
 else if(team.some(x=>x.kind==='guard'||x.role==='护法')){team.slice(0,2).forEach(x=>x.status['护盾值']=(x.status['护盾值']||0)+Math.floor(x.atk*1.3));log.push('⛨ 神阵连携：前排庇护')}
 else if(team.some(x=>x.kind==='aoe'||x.kind==='chain')){const a=team.find(x=>x.kind==='aoe'||x.kind==='chain');foes.slice(0,2).forEach(x=>damage(x,a.atk*.56,log,'✦ 五神联动·追击',false,a));log.push('✦ 神阵连携：仙法追击')}
}
function startBattle(){if(!S.lineup.length){msg('至少上阵一位神将');return}stopAutoBattle();battle=freshBattle();render()}
function battleTarget(actor,foes){const pool=alive(foes);if(!pool.length)return null;
 const front=pool.filter(x=>x.slot<2),rear=pool.filter(x=>x.slot>=2);
 if(actor.kind==='execute'&&rear.length)return lowest(rear);
 if(actor.kind==='chain'&&pool.some(x=>x.status['易伤']))return lowest(pool.filter(x=>x.status['易伤']));
 if(actor.fx==='break'&&front.some(x=>x.status['护盾值']>0))return lowest(front.filter(x=>x.status['护盾值']>0));
 if(['奇谋','控场'].includes(actor.role)&&rear.length&&actor.kind==='strike')return lowest(rear);
 return lowest(front.length?front:pool);
}
function beastPulse(b,log){for(let id of S.beastLine){if(id===null)continue;let pet=BEASTS[id],lv=S.beasts[id].level,good=alive(b.good),enemy=alive(b.enemy);if(!good.length||!enemy.length)break;let atk=80+lv*22+S.stage*3;if(pet.kind==='heal'){let x=lowest(good);heal(x,atk*2,log,`🐲${pet.name}`)}else if(pet.kind==='shield'||pet.kind==='ward'){good.forEach(x=>x.status['护盾值']=(x.status['护盾值']||0)+atk);log.push(`🐲${pet.name} 为全队加持护盾`)}else if(pet.kind==='energy'||pet.kind==='haste'){good.forEach(x=>x.energy=Math.min(100,x.energy+27));log.push(`🐲${pet.name} 恢复全队灵力`)}else{let t=pick(enemy);damage(t,atk*(pet.kind==='strike'?3:2),log,`🐲${pet.name}`);if(pet.kind==='burn')addStatus(t,'灼烧',2);if(pet.kind==='poison')addStatus(t,'中毒',2);if(pet.kind==='weaken')addStatus(t,'虚弱',2)}}}

function pathProc(b,a,log){if(!b.path||a.enemy)return;
 const path=b.path,e=alive(b.enemy),g=alive(b.good);if(!e.length||!g.length)return;
 let ch=b.pathCharge||0;const foe=lowest(e),friend=lowest(g),bomb=e.filter(x=>x.status['灼烧']);
 if(path==='flame'&&a.fx==='burn')ch++;
 if(path==='frost'&&a.fx==='freeze')ch++;
 if(path==='sword'&&(['mark','break'].includes(a.fx)||a.kind==='chain'))ch++;
 if(path==='thunder'&&(['shock','burn'].includes(a.fx)))ch++;
 if(path==='bulwark'&&(['guard','reflect','counter','shield'].includes(a.fx)||a.kind==='guard'))ch++;
 if(path==='lotus'&&(['heal','cleanse','regen','revive'].includes(a.fx)||a.kind==='heal'))ch++;
 if(ch>=2){ch-=2;
  if(path==='flame'&&bomb.length){for(const t of bomb)damage(t,t.max*.085,log,'🔥道统·离火燃爆',false,a)}
  else if(path==='frost'){addStatus(foe,'易伤',2);log.push('❄道统·玄冰碎甲：目标易伤')}
  else if(path==='sword')damage(foe,a.atk*1.65,log,'⚔道统·万剑归宗',false,a);
  else if(path==='thunder')e.slice(0,3).forEach(x=>damage(x,a.atk*.75,log,'⚡道统·九霄过载',false,a));
  else if(path==='bulwark'){for(const x of g){x.status['护盾值']=(x.status['护盾值']||0)+a.atk*.8;addStatus(x,'反震',2)}log.push('🛡道统·玄武反震：护盾加强')}
  else if(path==='lotus'){for(const x of g){heal(x,a.atk*.75,log,'🌸道统·青莲回天');delete x.status['灼烧']}log.push('🌸道统·青莲回天：净化灼烧')}
 }
 b.pathCharge=ch;
}

function doTurn(b){if(b.over)return;let log=b.log;b.round++;b.bondRoundCount=0;log.push(`—— 第 ${b.round} 回合 ——`);const order=[...b.good,...b.enemy].sort((a,z)=>z.speed-a.speed||Number(a.enemy)-Number(z.enemy)||a.slot-z.slot);log.push('⚡ 先手序列：'+order.filter(x=>x.hp>0).slice(0,5).map(x=>x.name).join(' → '));for(const actor of order){if(actor.hp<=0)continue;const side=actor.enemy?b.enemy:b.good,foes=actor.enemy?b.good:b.enemy,friends=side;if(!alive(foes).length)continue;if(!alive(foes).length)break;for(let s of ['灼烧','中毒','流血'])if(actor.status[s]>0){let hit=Math.max(15,actor.max*(s==='灼烧'?.034:.025));damage(actor,hit,log,s,true)}if(actor.hp<=0)continue;if((actor.status['眩晕']||actor.status['冻结']||actor.status['昏睡'])>0){log.push(`${actor.name} 被控制，无法行动`);tickStatus(actor);continue}if(actor.status['再生']||actor.passive==='灵泉'||actor.passive==='逐日'||actor.passive==='福泽')heal(actor,actor.max*.045,log,`${actor.name}·再生`);if(actor.passive==='月华'||actor.passive==='逍遥')if(Math.random()<.35)['沉默','灼烧','流血','中毒','虚弱','冻结'].forEach(s=>delete actor.status[s]);passiveTurnProc(b,actor,friends,foes,log);let use=actor.energy>=100&&!actor.status['沉默'];if(use){actor.energy=0;bondProc(b,actor,log);cast(actor,foes,friends,log);pathProc(b,actor,log)}else{let enemy=battleTarget(actor,foes);if(!enemy)break;let multiplier=actor.status['虚弱']?.72:1;let crit=Math.random()<(actor.passive==='天眼'||actor.passive==='夜袭'?.3:.12);let val=actor.atk*multiplier*(crit?1.65:1)*(.83+Math.random()*.28)*(actor.status['增攻']?1.18:1);damage(enemy,val,log,`${actor.name}·${basicSkillName(HEROS[actor.id])}${crit?'·暴击':''}`,false,actor);actor.energy=Math.min(100,actor.energy+48+(actor.passive==='迅捷'||actor.passive==='军师'?12:0));if(actor.passive==='追魂')heal(actor,val*.24,log,'追魂吸血')}tickStatus(actor)}if(b.round%2===0&&!b.over)beastPulse(b,log);autoBattleMiracle(b,log);let g=alive(b.good).length,e=alive(b.enemy).length;if(!g||!e||b.round>=38){b.over=true;b.win=(e===0&&g>0)||(b.round>=38&&g>e);if(b.win){let rewardStage=S.storyMode==='tower'?S.tower+3:S.stage;let j=260+rewardStage*38,gold=4200+rewardStage*350;S.jade+=j;S.gold+=gold;S.spirit+=7+Math.ceil(S.stage/2);S.dust+=8+Math.ceil(S.stage/3);S.essence+=15+Math.ceil(S.stage/3);S.victories++;log.push(`🏆 凯旋！仙玉+${j}、铜钱+${gold}、通用神魂+${7+Math.ceil(S.stage/2)}、灵材与异兽精魄入库。`);if(Math.random()<.37){let g={id:S.uid++,slot:rnd(4),rarity:pick([1,1,2,2,3]),level:1,seed:rnd(100)};S.gear.push(g);log.push(`🎁 掉落仙装：${gearName(g)}`)}if(S.storyMode==='tower'){
S.tower=(S.tower||1)+1;S.towerWins=(S.towerWins||0)+1;S.jade+=300;S.spirit+=10;
if((S.tower-1)%5===0){S.tickets+=5;log.push('🗼 通天塔五层突破：额外获得召唤符×5！')}
log.push(`🗼 通过通天塔第 ${S.tower-1} 层！额外仙玉+300、神魂+10。`)
}else S.stage++}else log.push('💀 神阵败退，升级后可以再次挑战。')}else if(log.length>130)log.splice(0,log.length-90)}
function tickStatus(actor){for(let k of Object.keys(actor.status))if(k!=='护盾值'){actor.status[k]--;if(actor.status[k]<=0)delete actor.status[k]}}

const SIGNATURES=[
 ['天火印','施放神通后给敌方随机单位叠加灼烧。'],
 ['归墟斩','施放神通后追击敌方最低生命目标。'],
 ['冰魄锁','施放神通后概率冻结尚未被控制的敌人。'],
 ['玄甲阵','施放神通后给气血最低队友增加护盾。'],
 ['灵泉引','施放神通后为最弱队友回复气血并清除灼烧。'],
 ['破阵诀','施放神通后击碎目标的护盾。'],
 ['雷霆击','施放神通后对带灼烧敌人产生雷火追加伤害。'],
 ['星轨步','施放神通后为己方下一位神仙充能。'],
 ['蚀骨毒','施放神通后给目标叠加中毒。'],
 ['月华守','施放神通后净化最低生命队友的控制。'],
 ['剑印','施放神通后标记敌方气血最低目标。'],
 ['续命术','施放神通后提升己方残血单位的生命。']
];
function signatureDesc(h,u){const i=(h.id*7+3)%SIGNATURES.length;
 const bonus=u?(u.star>=30?'·30星三段觉醒':u.star>=20?'·20星二段觉醒':u.star>=10?'·10星初觉':'·基础'):'·未结缘';
 return `【${SIGNATURES[i][0]}${bonus}】${SIGNATURES[i][1]}（神格系数 ${(1+(h.id%7)*.07).toFixed(2)}）`;
}

const SKILL_TIERS=[1,5,10,20,30];
const TALENT_MODES={
  1:[['破阵·神通强化','神通追加一次破阵追击，对敌人造成额外伤害。'],['护命·灵盾','施放神通后保护气血最低的队友。']],
  5:[['贯星·凝神','攻击时为一名队友补充灵力。'],['回春·渡厄','施放神通后回复最弱队友生命。']],
  10:[['咒印·扩散','使目标附加一层额外异常状态。'],['清灵·净心','驱散队友的异常并获得护盾。']],
  20:[['法相·连斩','对最低血量敌人追击一记高额伤害。'],['天罡·护阵','施法时为全部存活队友施加护盾。']],
  30:[['天命·绝杀','施放本命神通后对残血目标追加斩杀伤害。'],['涅槃·返生','施放本命神通时复活一位已阵亡队友。']]
};
function skillTreeOf(u){return u&&u.skillTree&&typeof u.skillTree==='object'&&!Array.isArray(u.skillTree)?u.skillTree:{}}
function nodeName(h,rank,branch){
 const suffix={1:['破式','守式'],5:['御灵','回元'],10:['劫印','净心'],20:['真诀','法域'],30:['终章','归元']}[rank][branch];
 return h.skill.replace(/[·\s]/g,'').slice(0,4)+'·'+suffix;
}
function buildSkillTree(h,u){let nodes=skillTreeOf(u);return `<div class="skilltree-frame"><div class="skilltree-heading"><div><small>DIVINE TECHNIQUES / AWAKEN</small><h3>命魂技能树 <span>★${u?.star||0}/30</span></h3></div><b>${Object.keys(nodes).length}/5 已习得</b></div><p class="skilltree-intro">五层命魂，攻守两路。每层任选其一；选择后直接改变战斗技能，允许自由切换流派。</p><div class="tree-track">${SKILL_TIERS.map((rank,i)=>{const ready=u&&u.star>=rank,v=nodes[rank];return `<section class="talent-tier ${ready?'unlocked':'locked'}"><div class="tier-meta"><span class="tree-star">★${rank}</span><div><strong>第${['一','二','三','四','五'][i]}重 · ${['觉脉','聚灵','化形','通玄','登神'][i]}</strong><small>${ready?(v!==undefined?'已觉醒 · 可切换':'可选择一条命魂路径'):`升至 ${rank} 星解锁`}</small></div></div><div class="tree-choices">${[0,1].map(branch=>{let d=TALENT_MODES[rank][branch],active=v===branch;return `<button class="tree-choice ${active?'selected':''}" data-act="chooseTalent" data-rank="${rank}" data-branch="${branch}" ${ready?'':'disabled'}><span class="talent-icon">${branch===0?'⚔':'◇'}</span><b>${nodeName(h,rank,branch)}</b><small>${d[1]}</small><span class="talent-state">${!ready?'尚未解锁':active?'✓ 已选择':'点击修习'}</span></button>`}).join('')}</div></section>`}).join('')}</div></div>`}
function learnSkill(rank,branch){const h=HEROS[selected],u=S.units[selected];if(!u){msg('请先通过召唤获得神将');return}if(!SKILL_TIERS.includes(rank)||![0,1].includes(branch)||u.star<rank){msg('命魂星级不足');return}
 if(!u.skillTree||typeof u.skillTree!=='object'||Array.isArray(u.skillTree))u.skillTree={};u.skillTree[rank]=branch;msg(h.name+'已领悟「'+nodeName(h,rank,branch)+'」');render();}
function skillTreeProc(a,foes,friends,log){if(a.enemy||!S.units[a.id])return;const h=HEROS[a.id],u=S.units[a.id],tree=skillTreeOf(u),e=alive(foes),g=alive(friends);if(!e.length||!g.length)return;
 const target=lowest(e),ally=lowest(g),pow=a.atk*(1+(a.id%9)*.015);
 for(const rank of SKILL_TIERS){if(u.star<rank)continue;let branch=tree[rank];if(branch!==0&&branch!==1)continue;
 if(rank===1){if(branch===0){damage(target,pow*(h.kind==='chain'?.48:h.kind==='aoe'?.29:.34),log,`✦${nodeName(h,rank,branch)}`,false,a);if(['burn','poison','mark','freeze'].includes(h.fx))addStatus(target,({burn:'灼烧',poison:'中毒',mark:'易伤',freeze:'冻结'})[h.fx],1)}else{ally.status['护盾值']=(ally.status['护盾值']||0)+Math.round(pow*(h.kind==='guard'?.95:.75));if(h.kind==='heal')heal(ally,pow*.35,log,nodeName(h,rank,branch));log.push(`◇ ${h.name} · 灵盾保护${ally.name}`)}}
 else if(rank===5){if(branch===0){const friend=g.find(x=>x!==a)||ally;friend.energy=Math.min(100,friend.energy+22);log.push(`✦ ${h.name} · ${friend.name}灵力+22`)}else heal(ally,pow*.82,log,nodeName(h,rank,branch));}
 else if(rank===10){if(branch===0){let map={burn:'灼烧',bleed:'流血',freeze:'冻结',poison:'中毒',mark:'易伤',shock:'眩晕',stun:'眩晕',silence:'沉默',weaken:'虚弱',break:'虚弱'};addStatus(target,map[h.fx]||'易伤',2);log.push(`✦ ${h.name} · 命魂咒印蔓延`)}else{['灼烧','中毒','流血','冻结','眩晕','沉默','虚弱'].forEach(s=>delete ally.status[s]);ally.status['护盾值']=(ally.status['护盾值']||0)+Math.round(pow*.8);log.push(`◇ ${h.name} · 净心护命`)}}
 else if(rank===20){if(branch===0){if(['aoe','wave'].includes(h.kind))e.forEach(x=>damage(x,pow*.58,log,nodeName(h,rank,branch),false,a));else if(h.kind==='chain')e.slice(0,2).forEach(x=>damage(x,pow*.86,log,nodeName(h,rank,branch),false,a));else damage(target,pow*1.35,log,nodeName(h,rank,branch),false,a)}else{g.forEach(x=>x.status['护盾值']=(x.status['护盾值']||0)+Math.round(pow*(h.kind==='guard'?.9:.7)));log.push(`◇ ${h.name} · 真诀庇护全队`)}}
 else if(rank===30){if(branch===0)damage(target,pow*(1.6+1.4*(1-target.hp/target.max)),log,nodeName(h,rank,branch),false,a);else{const down=friends.find(x=>x.hp<=0&&!x.revived);if(down){down.hp=Math.round(down.max*.36);down.revived=true;log.push(`◇ ${h.name} · ${down.name}涅槃重生`)}else heal(ally,pow*2,log,nodeName(h,rank,branch))}}
 }
}

function signatureProc(a,foes,friends,log){if(!alive(foes).length)return;let u=(!a.enemy&&S.units[a.id])||{star:1};let tier=u.star>=30?3:u.star>=20?2:u.star>=10?1:0;
 const power=a.atk*(.22+(a.id%7)*.02)*(1+tier*.28);
 const t=lowest(foes),f=lowest(friends);if(!t||!f)return;
 let i=(a.id*7+3)%12; if(i===0){addStatus(t,'灼烧',tier>=2?3:2);log.push(`♨ ${a.name}·天火印：灼烧${t.name}`)}
 else if(i===1){damage(t,power*(1+tier*.16),log,`${a.name}·归墟斩`,false,a)}
 else if(i===2){if(!t.status['冻结']&&Math.random()<.48+tier*.12){addStatus(t,'冻结',1);log.push(`❄ ${a.name}·冰魄锁：冻结${t.name}`)}}
 else if(i===3){f.status['护盾值']=(f.status['护盾值']||0)+Math.round(power*2.2);log.push(`⛨ ${a.name}·玄甲阵：护盾${f.name}`)}
 else if(i===4){heal(f,power*2.1,log,`${a.name}·灵泉引`);delete f.status['灼烧']}
 else if(i===5){let cut=Math.min(t.status['护盾值']||0,Math.floor(power*2.5));t.status['护盾值']-=cut;if(cut)log.push(`⚔ ${a.name}·破阵诀：破盾${cut}`)}
 else if(i===6){if(t.status['灼烧']){damage(t,power*1.7,log,`${a.name}·雷霆击`,false,a);if(tier>=2)addStatus(t,'眩晕',1)}}
 else if(i===7){const x=alive(friends).find(x=>x!==a)||f;x.energy=Math.min(100,x.energy+14+tier*8);log.push(`✧ ${a.name}·星轨步：为${x.name}充能`)}
 else if(i===8){addStatus(t,'中毒',2+tier);log.push(`☣ ${a.name}·蚀骨毒：毒染${t.name}`)}
 else if(i===9){['冻结','眩晕','沉默','昏睡'].forEach(x=>delete f.status[x]);if(tier>=2)f.status['护盾值']=(f.status['护盾值']||0)+Math.round(power);log.push(`☾ ${a.name}·月华守：净化${f.name}`)}
 else if(i===10){addStatus(t,'易伤',2);log.push(`⟡ ${a.name}·剑印：标记${t.name}`)}
 else{heal(f,power*2.4,log,`${a.name}·续命术`);if(tier===3)friends.filter(x=>x.hp<=0&&!x.revived).slice(0,1).forEach(x=>{x.revived=true;x.hp=Math.floor(x.max*.16)})}
}

function cast(a,foes,friends,log){let aliveEnemy=alive(foes),aliveFriends=alive(friends);if(!aliveEnemy.length)return;let asc=(!a.enemy&&S.units[a.id])?.star||1;
let power=a.atk*(1+((!a.enemy&&S.units[a.id])?S.units[a.id].artifact*.018:0))*(1+(asc>=10?.10:0)+(asc>=20?.13:0)+(asc>=30?.20:0))*(a.status['增攻']?1.18:1),target=battleTarget(a,aliveEnemy);if(a.passive==='神射'||a.passive==='审判')power*=1.15;log.push(`✨ ${a.name} 施展「${a.skill}」！`);let hit=(t,mult)=>{
 if(!t||t.hp<=0)return 0;
 let factor=1;
 if(t.status['易伤']&&(a.kind==='strike'||a.kind==='chain'||a.kind==='execute')){factor+=.45;delete t.status['易伤'];log.push(`⚔️ 剑痕追击：${a.name}引爆了易伤印记`)}
 if(t.status['冻结']&&(a.kind==='strike'||a.kind==='chain')){factor+=.38;delete t.status['冻结'];addStatus(t,'虚弱',1);log.push(`❄️ 玄冰碎甲：${a.name}击碎冰封追加伤害`)}
 if(t.status['灼烧']&&a.fx==='burn'){factor+=.4;log.push(`🔥 离火燃爆：${a.name}引动了目标的灼烧`)}
 if(t.status['护盾值']&&a.fx==='break'){let cut=Math.min(t.status['护盾值'],Math.round(power*1.7));t.status['护盾值']-=cut;log.push(`🗡️ 破盾克制：${a.name}击破${t.name} ${nfmt(cut)}护盾`)}
 let n=damage(t,power*mult*factor*(.88+Math.random()*.22)*(a.status['虚弱']?.73:1),log,a.skill,false,a);
 if(t.hp>0&&t.status['灼烧']&&a.fx==='shock'){
 delete t.status['灼烧'];damage(t,power*.85,log,'⚡ 雷火过载',false,a);
 log.push(`⚡ 雷火过载：${a.name}引爆火种并清除灼烧`)
 }
 return n;
 };switch(a.kind){case 'heal':{let t=lowest(aliveFriends);if(t)heal(t,power*3.4*(['仁心','慈悲','灵泉'].includes(a.passive)?1.22:1),log,a.skill);aliveFriends.filter(x=>x!==t).sort((x,y)=>x.hp/x.max-y.hp/y.max).slice(0,2).forEach(x=>heal(x,power*1.5,log,a.skill));break}case 'guard':aliveFriends.forEach(x=>{x.status['护盾值']=(x.status['护盾值']||0)+Math.round(power*1.2);addStatus(x,'防护',2);if(a.fx==='reflect'||a.fx==='counter')addStatus(x,'反震',2)});log.push('全队受到护盾与防护的庇佑');break;case 'bless':aliveFriends.forEach(x=>{x.energy=Math.min(100,x.energy+30);addStatus(x,'增攻',2);if(a.fx==='shield')x.status['护盾值']=(x.status['护盾值']||0)+power});log.push('全队增攻、灵力上涨');break;case 'execute':hit(target,2.7+(1-target.hp/target.max)*2);break;case 'strike':hit(target,a.fx==='pierce'?4.2:3.3);break;case 'control':hit(target,1.5);break;case 'chain':for(let i=0;i<3;i++)if(alive(foes).length)hit(pick(alive(foes)),1.32);break;case 'wave':case 'aoe':aliveEnemy.forEach(t=>hit(t,a.kind==='wave'?1.4:1.6));break}let applies=(a.kind==='wave'||a.kind==='aoe')?alive(foes):[lowest(foes)].filter(Boolean);let statusMap={burn:'灼烧',bleed:'流血',poison:'中毒',freeze:'冻结',stun:'眩晕',shock:'眩晕',silence:'沉默',sleep:'昏睡',charm:'虚弱',weaken:'虚弱',mark:'易伤',break:'虚弱',drain:'流血'};let status=statusMap[a.fx];if(status)applies.forEach(t=>{
if(Math.random()<(.5+(['天道','镇压','水魄'].includes(a.passive)?.25:0))){
if(status==='冻结'&&t.status['灼烧']){delete t.status['灼烧'];log.push(`🌊 水克火：${a.name}扑灭了${t.name}的灼烧`)}
addStatus(t,status,['眩晕','冻结','昏睡'].includes(status)?1:2)
}});if(a.fx==='shield')aliveFriends.forEach(t=>t.status['护盾值']=(t.status['护盾值']||0)+Math.floor(power*.6));if(a.fx==='cleanse')aliveFriends.forEach(t=>{['灼烧','流血','中毒','冻结','沉默','眩晕','虚弱','昏睡'].forEach(s=>delete t.status[s])});if(a.fx==='regen')aliveFriends.forEach(t=>addStatus(t,'再生',3));if(a.fx==='haste')aliveFriends.forEach(t=>t.energy=Math.min(100,t.energy+24));if(a.fx==='revive'){let dead=friends.find(t=>t.hp<=0&&!t.revived);if(dead){dead.revived=true;dead.hp=Math.floor(dead.max*.33);log.push(`🌸 ${dead.name} 被复活！`)}}if(a.fx==='drain')heal(a,power*.7,log,a.skill);if(a.passive==='巧心'||a.passive==='坚毅')aliveFriends.forEach(t=>t.status['护盾值']=(t.status['护盾值']||0)+Math.floor(power*.3));if(a.passive==='斗战'&&Math.random()<.28&&alive(foes).length)hit(lowest(foes),.85);signatureProc(a,foes,friends,log);skillTreeProc(a,foes,friends,log)}
